db_connect <- function(path="data/hcf.sqlite") { dir.create(dirname(path),showWarnings=FALSE,recursive=TRUE); con <- DBI::dbConnect(RSQLite::SQLite(),path); db_init(con); con }
db_init <- function(con) { DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS players (player_id TEXT PRIMARY KEY, player_name TEXT, age REAL, prior_injury INTEGER, experience_years REAL, archived INTEGER DEFAULT 0)"); DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS daily_entries (player_id TEXT, date TEXT, payload_json TEXT, PRIMARY KEY(player_id,date))"); DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS cached_outputs (player_id TEXT, date TEXT, payload_json TEXT, PRIMARY KEY(player_id,date))") }
db_upsert_player <- function(con,p) DBI::dbExecute(con,"INSERT INTO players VALUES (:player_id,:player_name,:age,:prior_injury,:experience_years,0) ON CONFLICT(player_id) DO UPDATE SET player_name=excluded.player_name,age=excluded.age,prior_injury=excluded.prior_injury,experience_years=excluded.experience_years",params=as.list(p))
db_players <- function(con) DBI::dbGetQuery(con,"SELECT * FROM players WHERE archived=0 ORDER BY player_name")
db_save_entry <- function(con,entry) DBI::dbExecute(con,"INSERT INTO daily_entries VALUES (:id,:dt,:js) ON CONFLICT(player_id,date) DO UPDATE SET payload_json=excluded.payload_json",params=list(id=entry$player_id,dt=as.character(entry$date),js=jsonlite::toJSON(entry,auto_unbox=TRUE,null="null")))
db_entries <- function(con,id) { x <- DBI::dbGetQuery(con,"SELECT payload_json FROM daily_entries WHERE player_id=:id ORDER BY date",params=list(id=id)); if(!nrow(x)) return(data.frame()); as.data.frame(data.table::rbindlist(lapply(x$payload_json,jsonlite::fromJSON),fill=TRUE)) }
db_cache_output <- function(con,id,date,value) DBI::dbExecute(con,"INSERT INTO cached_outputs VALUES (:id,:dt,:js) ON CONFLICT(player_id,date) DO UPDATE SET payload_json=excluded.payload_json",params=list(id=id,dt=as.character(date),js=jsonlite::toJSON(value,auto_unbox=TRUE)))
